            add4(p, q, limbs, m, e, neg, b, 0, 0, 5, 6, true);     // - a.x a.x c.y d.x
            add4(p, q, limbs, m, e, neg, b, 0, 2, 2, 5, true);     // - a.x b.x b.x c.y
            add4(p, q, limbs, m, e, neg, b, 0, 2, 2, 7, false);     // + a.x b.x b.x d.y
            add4(p, q, limbs, m, e, neg, b, 0, 3, 3, 5, true);     // - a.x b.y b.y c.y
            add4(p, q, limbs, m, e, neg, b, 0, 3, 3, 7, false);     // + a.x b.y b.y d.y
            add4(p, q, limbs, m, e, neg, b, 0, 3, 4, 4, false);     // + a.x b.y c.x c.x
            add4(p, q, limbs, m, e, neg, b, 0, 3, 5, 5, false);     // + a.x b.y c.y c.y
            add4(p, q, limbs, m, e, neg, b, 0, 3, 6, 6, true);     // - a.x b.y d.x d.x
            add4(p, q, limbs, m, e, neg, b, 0, 3, 7, 7, true);     // - a.x b.y d.y d.y
            add4(p, q, limbs, m, e, neg, b, 0, 4, 4, 7, true);     // - a.x c.x c.x d.y
            add4(p, q, limbs, m, e, neg, b, 0, 5, 5, 7, true);     // - a.x c.y c.y d.y
            add4(p, q, limbs, m, e, neg, b, 0, 5, 6, 6, false);     // + a.x c.y d.x d.x
            add4(p, q, limbs, m, e, neg, b, 0, 5, 7, 7, false);     // + a.x c.y d.y d.y
            add4(p, q, limbs, m, e, neg, b, 1, 1, 2, 5, false);     // + a.y a.y b.x c.y
            add4(p, q, limbs, m, e, neg, b, 1, 1, 2, 7, true);     // - a.y a.y b.x d.y
            add4(p, q, limbs, m, e, neg, b, 1, 1, 3, 4, true);     // - a.y a.y b.y c.x
            add4(p, q, limbs, m, e, neg, b, 1, 1, 3, 6, false);     // + a.y a.y b.y d.x
            add4(p, q, limbs, m, e, neg, b, 1, 1, 4, 7, false);     // + a.y a.y c.x d.y
            add4(p, q, limbs, m, e, neg, b, 1, 1, 5, 6, true);     // - a.y a.y c.y d.x
            add4(p, q, limbs, m, e, neg, b, 1, 2, 2, 4, false);     // + a.y b.x b.x c.x
            add4(p, q, limbs, m, e, neg, b, 1, 2, 2, 6, true);     // - a.y b.x b.x d.x
            add4(p, q, limbs, m, e, neg, b, 1, 2, 4, 4, true);     // - a.y b.x c.x c.x
            add4(p, q, limbs, m, e, neg, b, 1, 2, 5, 5, true);     // - a.y b.x c.y c.y
            add4(p, q, limbs, m, e, neg, b, 1, 2, 6, 6, false);     // + a.y b.x d.x d.x
            add4(p, q, limbs, m, e, neg, b, 1, 2, 7, 7, false);     // + a.y b.x d.y d.y
            add4(p, q, limbs, m, e, neg, b, 1, 3, 3, 4, false);     // + a.y b.y b.y c.x
            add4(p, q, limbs, m, e, neg, b, 1, 3, 3, 6, true);     // - a.y b.y b.y d.x
            add4(p, q, limbs, m, e, neg, b, 1, 4, 4, 6, false);     // + a.y c.x c.x d.x
            add4(p, q, limbs, m, e, neg, b, 1, 4, 6, 6, true);     // - a.y c.x d.x d.x
            add4(p, q, limbs, m, e, neg, b, 1, 4, 7, 7, true);     // - a.y c.x d.y d.y
            add4(p, q, limbs, m, e, neg, b, 1, 5, 5, 6, false);     // + a.y c.y c.y d.x
            add4(p, q, limbs, m, e, neg, b, 2, 2, 4, 7, true);     // - b.x b.x c.x d.y
            add4(p, q, limbs, m, e, neg, b, 2, 2, 5, 6, false);     // + b.x b.x c.y d.x
            add4(p, q, limbs, m, e, neg, b, 2, 4, 4, 7, false);     // + b.x c.x c.x d.y
            add4(p, q, limbs, m, e, neg, b, 2, 5, 5, 7, false);     // + b.x c.y c.y d.y
            add4(p, q, limbs, m, e, neg, b, 2, 5, 6, 6, true);     // - b.x c.y d.x d.x
            add4(p, q, limbs, m, e, neg, b, 2, 5, 7, 7, true);     // - b.x c.y d.y d.y
            add4(p, q, limbs, m, e, neg, b, 3, 3, 4, 7, true);     // - b.y b.y c.x d.y
            add4(p, q, limbs, m, e, neg, b, 3, 3, 5, 6, false);     // + b.y b.y c.y d.x
            add4(p, q, limbs, m, e, neg, b, 3, 4, 4, 6, true);     // - b.y c.x c.x d.x
            add4(p, q, limbs, m, e, neg, b, 3, 4, 6, 6, false);     // + b.y c.x d.x d.x
            add4(p, q, limbs, m, e, neg, b, 3, 4, 7, 7, false);     // + b.y c.x d.y d.y
            add4(p, q, limbs, m, e, neg, b, 3, 5, 5, 6, true);     // - b.y c.y c.y d.x
            return compare(p, q, limbs);
        }
    }
}
